## What are you doing?
```
const Sequelize = require('sequelize');
const sequelize = new Sequelize('test-db', '', '', { host: 'localhost', dialect: 'postgres', operatorsAliases: false, logging: false });

const User = sequelize.define('User', {
  name: Sequelize.STRING(200),
  status: Sequelize.ENUM('active', 'inactive', 'unverified'),
}, {
  scopes: {
    active: {
      where: {
        status: 'active',
      },
    },
  },
});

async function main () {
  await sequelize.sync({ force: true });
  await Promise.all([
    User.create({ name: 'Active User 1', status: 'active' }),
    User.create({ name: 'Active User 2', status: 'active' }),
    User.create({ name: 'Inactive User 1', status: 'inactive' }),
    User.create({ name: 'Inactive User 2', status: 'inactive' }),
  ]);

  const unscopedUser = await User.findOne({ where: { name: 'Inactive User 1' } });
  const unscopedUsers = await User.findAll({ where: { status: 'inactive' } });
  const scopedUser = await User.scope('active').findOne({ where: { name: 'Active User 1' } });
  const scopedUsers = await User.scope('active').findAll();

  console.log('unscopedUser constructor is User ==', unscopedUser.constructor === User); // true
  console.log('unscopedUsers constructors are User ==', unscopedUsers.every(i => i.constructor === User)); // true
  console.log('scopedUser constructor is User ==', scopedUser.constructor === User); // false
  console.log('scopedUsers constructors are User ==', scopedUsers.every(i => i.constructor === User)); // false

  process.exit(0);
}

main();
```

## What do you expect to happen?
I expect the object instance constructors to always be `User` even if I used `.scope()` to retrieve it.

## What is actually happening?
When `.scope()` is used during retrieval the instance constructor is no longer `User`.

__Dialect:__ postgres
__Dialect version:__ ??
__Database version:__ 10.3
__Sequelize version:__ 4.37.10
__Tested with latest release:__ Yes (4.37.10)

